class ST(object):
    s: str
    leftdiff: int
    rightmax: int


def main():
    N = int(input())
    PM = []
    PP = []
    MP = []
    MM = []
    for i in range(N):
        s = input()
        st = ST()
        st.s = s

        left = 0
        right = 0
        rightmax = 0
        for c in s:
            if c == "(":
                left += 1
            else:
                right += 1
            rightmax = max(rightmax, right - left)
        st.leftdiff = (left - right)
        st.rightmax = rightmax

        if st.leftdiff > 0 and st.rightmax <= 0:
            PM.append(st)
        if st.leftdiff > 0 and st.rightmax > 0:
            PP.append(st)
        if st.leftdiff <= 0:
            MM.append(st)

        # if st.leftdiff <= 0 and st.rightmax <= 0:
        #     MM.append(st)
        # if st.leftdiff <= 0 and st.rightmax > 0:
        #     MP.append(st)

    nleft = 0
    for st in PM:
        nleft += st.leftdiff
    for st in sorted(PP, key=lambda _st: _st.rightmax):
        if nleft - st.rightmax < 0:
            print("No")
            return
        nleft += st.leftdiff
    for st in sorted(MM, key=lambda _st: _st.rightmax):
        if nleft - st.rightmax < 0:
            print("No")
            return
        nleft += st.leftdiff
    if nleft == 0:
        print("Yes")
    else:
        print("No")


main()

