N = int(input())
S = [input().rstrip() for _ in range(N)]

def calc(S):
    now = 0
    ret = 0
    for s in S:
        if s == '(':
            now += 1
        else:
            now -= 1
        if now < 0:
            ret = min(ret, now)
    return ret

H = []
P = []
L = []

for s in S:
    c = calc(s)
    if c == 0:
        H.append(s)
    else:
        l = s.count('(')
        r = len(s) - l
        if l > r:
            P.append((-c, s))
        else:
            L.append((-c, s))

P.sort()
L.sort(reverse=True)
P = [s for _, s in P]
L = [s for _, s in L]

ans = ''.join(H + P + L)
l = ans.count('(')
r = len(ans) - l

if l == r and calc(ans) == 0:
    print('Yes')
else:
    print('No')

