        elevation, bottom = 0, 0
        for grad in grads:
            bottom = elevation + grad[0]
            if bottom < 0:
                return False
            elevation += grad[1]

        if elevation == 0:
            return True
        else:
            return False

    if is_good(grads_positive) and is_good(grads_negative):
        return True
    else:
        return False


