import math

class SegmentTree:
    def __init__(self, n):
        """初期化
        num : nより大きい最小の2のべき乗
        """
        self.num = 2**(int(math.log2(n))+1)
        self.seg = [(-1, i) for i in range(2*self.num-1)]
        for i in range(n):
            self.update(i, 0)

    def update(self,i,x):
        """update(i,x):Aiをxに更新する
        """
        k = i + self.num - 1
        while k >= 0:
            if x>self.seg[k][0]:
                val = x
                ind = i
                self.seg[k] = (val, ind)
                k = (k-1)//2
            else:
                break

    def query(self,a,b,k=0,l=0,r=None):
        """query(a,b,0,0,num):[a,b)の最大値
        """
        if r is None:
            r = self.num
        if r <= a or b <= l:
            return (-float("inf"), None)
        elif a <= l and r <= b:
            return self.seg[k]
        else:
            return max(self.query(a,b,2*k+1,l,(l+r)//2),self.query(a,b,2*k+2,(l+r)//2,r))

    ######################################################


