import numpy  as np


def parse(brackets):
    m = 0
    f = 0
    for c in brackets:
        if c == "(":
            f += 1
        else:
            f -= 1
        if m > f:
            m = f
    return m, f


def climbable(g, reverse=False):
    if reverse:
        g = g * np.array([1,-1])
        g[:,0] = np.sum(g)
    top = np.sum(g[g[:,0]>=0][:,1])
    v = g[g[:,0]<0]
    while len(v) > 0:
        flag = v[:,0]+top>=0
        if not np.any(flag):
            return False
        if np.all(flag):
            return True
        top += np.sum(v[flag][:,1])
        v = v[np.logical_not(flag)]
    return True


