    n = int(input())
    g = np.stack([np.array(parse(input().strip()), dtype=int) for _ in range(n)])
    if np.sum(g, axis=0)[1] != 0:
        return False
    f = g[:, 1]
    return climbable(g[f>=0]) and climbable(g[f<0], reverse=True)


