   /bin/bash -c "pypy3 /vo/$(basename $0) < /vo/input.txt"
exit $?
'''
import sys

def _s(): return sys.stdin.readline().strip()

def _i(): return int(sys.stdin.readline().strip())

def parse(s):
    l, r = 0, 0
    for c in s:
        if c == '(':
            r += 1
        else:
            if r>0:
                r-=1
            else:
                l+=1
    return (r,l)


def main():
    n = _i()
    p = list(filter(lambda x: x !=(0,0), [parse(_s()) for _ in range(n)]))
    p.sort(key= lambda x: (-x[0],x[1]))

    r = 0
    for pi in p:
        rr, ll = pi
        if ll > r:
            return 'No'
        r += (rr - ll)

    return 'Yes' if r == 0 else 'No'

if __name__ == "__main__":
    print(main())

