input=sys.stdin.readline
def count(s):
    m=0
    e=0
    for t in s:
        if t=='(':
            e+=1
        else:
            e-=1
        m=min(m,e)
    return (e,m)

def solve(P,N):
    s=0
    for _,e in P:
        s+=e
    for _,e in N:
        s+=e
    if s!=0:
        return 'No'
    s=0
    for m,e in P:
        if s+m<0:
            return 'No'
        s+=e
        if s<0:
            return 'No'
    for m,e in N:
        if s+m<0:
            return 'No'
        s+=e
        if s<0:
            return 'No'
    return 'Yes'

def main():
    n=int(input())
    S=[input().strip() for _ in range(n)]
    P,N=[],[]
    for s in S:
        e,m=count(s)
        #print(s,e,m)
        if e>0:
            P.append((m,e))
        else:
            N.append((m,e))
    P.sort(reverse=True)
    N.sort(reverse=True)
    #print(P,N)
    print(solve(P,N))

